<?php
declare(strict_types=1);
namespace App\Modules\Tourism\Controllers;
use App\Core\Auth;use App\Core\Authorization;use App\Core\Controller;use App\Modules\Tourism\Services\TourismStayService;use RuntimeException;use Throwable;
final class TourismStayController extends Controller{private TourismStayService $s;private Authorization $a;public function __construct(){$this->s=new TourismStayService();$this->a=new Authorization();}private function allow(string $p,string $r='/tourism/stays'):bool{try{$this->a->authorize($p);return true;}catch(RuntimeException $e){flash('error',$e->getMessage());redirect($r);return false;}}public function index():void{if(!$this->allow('tourism.stays.view'))return;$t=(int)Auth::tenantId();$trash=($_GET['view']??'')==='trash';$this->view('Tourism::Stays.index',['title'=>$trash?'Deleted Stays':'Tourism Stays','stays'=>$this->s->all($t,$trash),'trash'=>$trash]);}public function create():void{if(!$this->allow('tourism.stays.create','/tourism'))return;$t=(int)Auth::tenantId();$this->view('Tourism::Stays.create',['title'=>'Add Stay','providers'=>$this->s->providers($t),'destinations'=>$this->s->destinations($t),'locations'=>$this->s->locations()]);}public function store():void{if(!$this->allow('tourism.stays.create','/tourism/stays'))return;$t=(int)Auth::tenantId();try{$id=$this->s->create($t,$_POST,(int)Auth::id(),$_FILES['logo']??null,$_FILES['cover_image']??null);flash('success','Tourism stay created successfully.');redirect('/tourism/stays/'.$id);}catch(Throwable $e){$this->view('Tourism::Stays.create',['title'=>'Add Stay','providers'=>$this->s->providers($t),'destinations'=>$this->s->destinations($t),'locations'=>$this->s->locations(),'error'=>$e->getMessage(),'old'=>$_POST]);}}public function show(int $id):void{if(!$this->allow('tourism.stays.view','/tourism/stays'))return;$t=(int)Auth::tenantId();$r=$this->s->find($t,$id);if(!$r)abort(404);$this->view('Tourism::Stays.show',['title'=>$r['name'],'record'=>$r,'rooms'=>$this->s->rooms($t,$id)]);}public function edit(int $id):void{if(!$this->allow('tourism.stays.edit','/tourism/stays'))return;$t=(int)Auth::tenantId();$r=$this->s->find($t,$id);if(!$r)abort(404);$this->view('Tourism::Stays.edit',['title'=>'Edit Stay','record'=>$r,'rooms'=>$this->s->rooms($t,$id),'providers'=>$this->s->providers($t),'destinations'=>$this->s->destinations($t),'locations'=>$this->s->locations()]);}public function update(int $id):void{if(!$this->allow('tourism.stays.edit','/tourism/stays'))return;$t=(int)Auth::tenantId();try{$this->s->update($t,$id,$_POST,(int)Auth::id(),$_FILES['logo']??null,$_FILES['cover_image']??null);flash('success','Tourism stay updated successfully.');redirect('/tourism/stays/'.$id);}catch(Throwable $e){$r=$this->s->find($t,$id)??$_POST;$this->view('Tourism::Stays.edit',['title'=>'Edit Stay','record'=>$r,'rooms'=>$this->s->rooms($t,$id),'providers'=>$this->s->providers($t),'destinations'=>$this->s->destinations($t),'locations'=>$this->s->locations(),'error'=>$e->getMessage()]);}}public function destroy(int $id):void{if(!$this->allow('tourism.stays.delete','/tourism/stays'))return;try{$this->s->delete((int)Auth::tenantId(),$id,(int)Auth::id());flash('success','Stay moved to Trash.');}catch(Throwable $e){flash('error',$e->getMessage());}redirect('/tourism/stays');}public function restore(int $id):void{if(!$this->allow('tourism.stays.delete','/tourism/stays?view=trash'))return;try{$this->s->restore((int)Auth::tenantId(),$id,(int)Auth::id());flash('success','Stay restored.');}catch(Throwable $e){flash('error',$e->getMessage());}redirect('/tourism/stays?view=trash');}}
